/** Rider-to-mount relationship. Occupied seats are exclusive; mounted characters bypass walking physics. */
export type MountedData = {
  vehicle: string;
  seat: string;
};
/** Desired planar move direction + jump flag, consumed by the character controller. */
export type MoveIntentData = {
  dir: [number, number];
  jump: boolean;
};
/** Attach to a parent entity: transform becomes parent.transform × localTransform each tick. */
export type ParentData = {
  id: string;
  onParentDestroyed?: 'destroy' | 'detach';
};
/** Deterministic XY platform controller: gravity, swept wall/floor/ceiling collision, jump buffering and coyote time. */
export type PlatformBodyData = {
  halfExtents: [number, number];
  vel?: [number, number];
  speed?: number;
  acceleration?: number;
  gravity?: number;
  jumpSpeed?: number;
  grounded?: boolean;
  coyoteTicks?: number;
  bufferTicks?: number;
  grace?: number;
  buffered?: number;
};
/** Input to a platformBody. Scripts translate declared commands to this component. */
export type PlatformIntentData = {
  move: number;
  jump?: boolean;
  jumpHeld?: boolean;
};
/** Static XY solid for physics.engine=platformer; Z is ignored. */
export type PlatformSolidData = {
  halfExtents: [number, number];
  oneWay?: boolean;
};
/** Client render contract: a primitive, a gltf asset (by project asset id) with optional sub-node, material override, shadows, and clip playback, or a capability-registered kind. */
export type RenderableData = {
  kind: 'primitive' | 'gltf' | 'ambient-vehicle' | 'figure';
  ref: string;
  materialRef?: string;
  primitive?: {
    size?: [number, number, number];
  };
  node?: string;
  visible?: boolean;
  shadows?: {
    cast?: boolean;
    receive?: boolean;
  };
  animation?: {
    clip: string;
    speed?: number;
    loop?: 'repeat' | 'once' | 'pingpong';
    paused?: boolean;
    pausedAtTick?: number;
    startTick?: number;
  };
  lod?: 'auto' | 0 | 1 | 2;
};
/** 3D rigid-body dynamics: dynamic, fixed, or kinematicPosition (characters). */
export type RigidbodyData = {
  body: 'dynamic' | 'fixed' | 'kinematicPosition';
  gravityScale?: number;
  linearDamping?: number;
  angularDamping?: number;
  ccd?: boolean;
  lockRot?: boolean;
};
/** One-shot velocity set; consumed the tick it is applied. */
export type SetVelocityData = {
  linear?: [number, number, number];
  angular?: [number, number, number];
};
/** Named tag for selecting/grouping entities (e.g. tag.name === "enemy"). */
export type TagData = {
  name: string;
  [key: string]: unknown;
};
/** Snapshot-safe countdown timers that emit events (one-shot or repeating). Replaces callbacks. */
export type TimerData = {
  timers: {
    id: string;
    ticksLeft: number;
    event: string;
    payload?: unknown;
    repeatEvery?: number;
  }[];
};
/** World position + orientation. pos is required; rot defaults to identity. */
export type TransformData = {
  pos: [number, number, number];
  rot?: [number, number, number, number];
  scale?: [number, number, number];
  teleport?: boolean;
};
/** Data-driven value animation over ticks: component + select-style path, lerp with easing. */
export type TweenData = {
  tweens: {
    id?: string;
    component: string;
    path: string;
    from?: number | number[];
    to: number | number[];
    ticks: number;
    elapsed?: number;
    easing?: 'linear' | 'quadIn' | 'quadOut' | 'quadInOut' | 'cubicIn' | 'cubicOut' | 'cubicInOut';
    loop?: 'none' | 'loop' | 'pingpong';
    emitOnComplete?: string;
  }[];
};
/** External wheeled-vehicle instance: stable id, paint, complete physics tuning, and GLB bindings. */
export type VehicleData = {
  kind: string;
  color: string;
  spec: {
    label: string;
    width: number;
    length: number;
    height: number;
    centerOfMass: [number, number, number];
    wheelbase: number;
    wheelTrack: number;
    wheelRadius: number;
    mass: number;
    engineForce: number;
    maxSpeed: number;
    reverseSpeed: number;
    brakeDeceleration: number;
    maxSteer: number;
    grip: number;
    driverEye: [number, number, number];
    steeringRate: number;
    steeringFadeSpeed: number;
    rollingResistance: number;
    aerodynamicResistance: number;
    terrainAlignRate: number;
    supportTolerance: number;
    maxStepHeight: number;
    maxSlope: number;
    drive?: 'front' | 'rear' | 'all';
    corneringStiffness?: number;
    brakeBias?: number;
    yawInertia?: number;
    rollStiffness?: number;
    pitchStiffness?: number;
    suspensionFrequency?: number;
    suspensionDamping?: number;
    cycle?: {
      maxLean: number;
      riderLean: number;
      handlebarPivot: [number, number, number];
      grips: [[number, number, number], [number, number, number]];
      footrests: [[number, number, number], [number, number, number]];
      pedals?: {
        center: [number, number, number];
        radius: number;
        halfWidth: number;
        ratio: number;
      };
    };
  };
  visual: {
    wheelNodes: string[];
    frontWheelNodes: string[];
    steeringWheelNode?: string;
    paintMaterial: string;
    interior?: {
      nodes: string[];
      sources?: Record<string, {
          component: string;
          path: (string | number)[];
        }>;
      bindings: {
        node: string;
        source: string;
        property: 'rotation' | 'position';
        axis: 'x' | 'y' | 'z';
        scale?: number;
        offset?: number;
        keys?: [number, number][];
        ease?: 'linear' | 'smooth';
        min?: number;
        max?: number;
      }[];
    };
    animation?: {
      sources?: Record<string, {
          component: string;
          path: (string | number)[];
        }>;
      bindings: {
        node: string;
        source: string;
        property: 'rotation' | 'position';
        axis: 'x' | 'y' | 'z';
        scale?: number;
        offset?: number;
        keys?: [number, number][];
        ease?: 'linear' | 'smooth';
        min?: number;
        max?: number;
      }[];
    };
  };
};
/** Driver intent: signed throttle (negative brakes then reverses), signed steering (positive right), service brake and optional handbrake. */
export type VehicleInputData = {
  throttle: number;
  steering: number;
  brake: boolean;
  handbrake?: boolean;
};
/** Snapshot-safe chassis state. Speeds in m/s, angles in radians; owned by installVehicles. */
export type VehicleStateData = {
  speed: number;
  steer: number;
  yaw: number;
  pitch: number;
  roll: number;
  vy: number;
  grounded: boolean;
  waitingForTerrain: boolean;
  wheelAngle: number;
  pedalAngle?: number;
  lateralSpeed?: number;
  yawRate?: number;
  bodyPitch?: number;
  bodyPitchRate?: number;
  bodyRoll?: number;
  bodyRollRate?: number;
  skid?: number;
};
/** Opt-in per-tick body velocity mirror (presence = subscription; plugin-written). */
export type VelocityData = {
  linear: [number, number, number];
  angular: [number, number, number];
};
/** Deterministic swells and current for boats; heights and coverage come from the host water field. */
export type WaterData = {
  waves?: {
    amplitude: number;
    wavelength: number;
    direction: number;
    speed: number;
  }[];
  current?: [number, number];
};
/** Singleton physical atmosphere and visual weather: temperature, pressure, humidity, wind, independent cloud cover, precipitation and visibility. Readable by scripts and physics; see guide/weather.md. */
export type WeatherData = {
  atmosphere?: {
    temperatureK?: number;
    pressurePa?: number;
    relativeHumidity?: number;
    windVelocity?: [number, number, number];
    referenceAltitude?: number;
    gasConstant?: number;
  };
  visibility?: number;
  clouds?: {
    coverage?: number;
    density?: number;
    baseAltitude?: number;
    thickness?: number;
    scale?: number;
  };
  precipitation?: {
    kind?: 'none' | 'rain' | 'snow';
    intensity?: number;
  };
  wind?: {
    referenceHeight?: number;
    shear?: number;
    turbulence?: number;
    gusts?: number;
    terrain?: number;
  };
  seed?: number;
};
/** A building generated at runtime from an outline in the entity frame, styled by a molen/archstyle@1 in the loaded pack; rendered by the worldgen client entity layer. */
export type WorldgenBuildingData = {
  style: string;
  appearance?: {
    wall?: string;
    trim?: string;
  };
  storefronts?: {
    identity: string;
    at: [number, number];
    signModel: string;
    signSize?: [number, number];
    accent: string;
    width?: number;
  }[];
  outline: [number, number][];
  holes?: [number, number][][];
  height?: number;
  levels?: number;
  labels?: string[];
  seed?: string;
  tier?: number;
  [key: string]: unknown;
};

